CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE login_attempts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, email text NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX login_attempts_email_time ON login_attempts(email,attempted_at);
CREATE TABLE areas (id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, slug text NOT NULL UNIQUE, name text NOT NULL, color text NOT NULL);
CREATE TABLE courses (id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE topics (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, course_id smallint NOT NULL REFERENCES courses(id), name text NOT NULL, UNIQUE(course_id,name));
CREATE TABLE sources (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, url text, source_type text NOT NULL DEFAULT 'original' CHECK(source_type IN ('original','historical','reference')));
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id integer NOT NULL REFERENCES topics(id), source_id integer NOT NULL REFERENCES sources(id), difficulty text NOT NULL CHECK(difficulty IN ('basica','intermedia','avanzada')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE question_areas (question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE, area_id smallint NOT NULL REFERENCES areas(id), PRIMARY KEY(question_id,area_id));
CREATE TABLE question_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1, statement text NOT NULL, explanation text NOT NULL, approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(question_id,version));
CREATE TABLE question_choices (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, question_version_id uuid NOT NULL REFERENCES question_versions(id) ON DELETE CASCADE, label char(1) NOT NULL CHECK(label IN ('A','B','C','D','E')), content text NOT NULL, is_correct boolean NOT NULL DEFAULT false, UNIQUE(question_version_id,label));
CREATE UNIQUE INDEX one_correct_choice ON question_choices(question_version_id) WHERE is_correct;
CREATE TABLE templates (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, description text NOT NULL, kind text NOT NULL CHECK(kind IN ('video','image','carousel')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE template_versions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, template_id integer NOT NULL REFERENCES templates(id), version integer NOT NULL DEFAULT 1, accent char(7) NOT NULL DEFAULT '#C80727', duration_seconds integer NOT NULL DEFAULT 15 CHECK(duration_seconds BETWEEN 6 AND 60), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(template_id,version));
CREATE TABLE batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,idempotency_key));
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), original_name text NOT NULL, storage_path text NOT NULL UNIQUE, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE video_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES batches(id), question_version_id uuid NOT NULL REFERENCES question_versions(id), template_version_id integer NOT NULL REFERENCES template_versions(id), provider text NOT NULL CHECK(provider IN ('demo','runway')), status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','generating','rendering','completed','failed','needs_attention','cancelled')), estimated_cost_cents integer NOT NULL DEFAULT 0 CHECK(estimated_cost_cents>=0), output_asset_id uuid REFERENCES media_assets(id), error_message text, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(batch_id,question_version_id));
CREATE INDEX jobs_status_created_idx ON video_jobs(status,created_at);
CREATE TABLE provider_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL UNIQUE REFERENCES video_jobs(id), state text NOT NULL CHECK(state IN ('submitting','submitted','succeeded','failed','uncertain')), remote_task_id text UNIQUE, output_path text, failure_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_heartbeats (worker_id text PRIMARY KEY, last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, job_id uuid NOT NULL REFERENCES video_jobs(id), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX job_events_job_idx ON job_events(job_id,created_at);
CREATE TABLE job_assets (job_id uuid NOT NULL REFERENCES video_jobs(id), asset_id uuid NOT NULL REFERENCES media_assets(id), ordinal smallint NOT NULL DEFAULT 0, PRIMARY KEY(job_id,asset_id), UNIQUE(job_id,ordinal));
